INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('nikotin-jugendliche-oesterreich-vapes-nikotinbeutel-social-media','Nikotin bei Jugendlichen: Lungenärzte warnen vor Vapes und Pouches','Fast drei von zehn 14- bis 17-Jährigen haben im letzten Monat gevapt. Beim Pneumologie-Kongress in Salzburg warnen Lungenärzte vor Social Media als Treiber – und setzen auf digitale Ausstiegshilfen.','Nikotin bei Jugendlichen ist in Österreich längst nicht mehr nur eine Frage der klassischen Zigarette. E-Zigaretten und Nikotinbeutel haben bei Schülerinnen und Schülern stark an Bedeutung gewonnen. Darauf hat die Österreichische Gesellschaft für Pneumologie (ÖGP) zum Abschluss ihrer 50. Jahrestagung hingewiesen, die von 22. bis 24. Oktober 2026 in Salzburg stattfand. Im Mittelpunkt stand die Frage, welche Rolle soziale Medien beim Einstieg spielen – und wie digitale Angebote beim Aufhören helfen können.

## Nikotin bei Jugendlichen: Die aktuellen Zahlen

Die Fachgesellschaft stützt sich auf zwei Erhebungen. Laut der österreichischen LEAD-Studie greifen knapp 8 Prozent der unter 18-Jährigen täglich zur E-Zigarette. Die ESPAD-Schülerbefragung zeigt ein noch breiteres Bild:

- 29 Prozent der 14- bis 17-Jährigen haben in den vergangenen 30 Tagen eine E-Zigarette verwendet.
- 17 Prozent haben im selben Zeitraum Nikotinbeutel (sogenannte Pouches) konsumiert.
- Besonders Mädchen fühlen sich laut ÖGP von bunt gestalteten Vapes mit süßen Aromen angesprochen.

Nach Darstellung der Lungenärzte handelt es sich bei E-Zigaretten und Nikotinbeuteln um Konsumprodukte und nicht um zugelassene Mittel zur Rauchentwöhnung. Nikotinsalze und ein angehobener pH-Wert sorgen dafür, dass das Nikotin sehr rasch im Körper ankommt. In Kombination mit auffälligem Design und Geschmacksrichtungen wie Früchten oder Süßigkeiten entstehe so ein Produkt, das gezielt junge Käufer anspreche. Viele Konsumentinnen und Konsumenten würden in der Folge abhängig.

## Social Media als Treiber

Ein zentraler Befund betrifft die Plattform TikTok. Eine Auswertung von Videos über Nikotinbeutel ergab, dass 79 Prozent der analysierten Clips die Produkte in einem positiven Licht zeigen – obwohl Werbung für Nikotinprodukte auf der Plattform offiziell untersagt ist. Inhalte, die Konsum als lässig oder harmlos darstellen, erreichen Jugendliche damit dennoch in großer Zahl.

Der Pneumologe Lukasz Antoniewicz, Oberarzt an der Klinischen Abteilung für Pulmologie der MedUni Wien und Leiter der Arbeitsgruppe „Allianz Nikotinfrei“ der Austrian Respiratory Coalition, sieht die Verantwortung nicht bei den einzelnen Jugendlichen. Das Problem sei vielmehr eine Branche, die laufend neue Wege suche, junge Menschen an Nikotin zu binden. Die ÖGP weist zudem darauf hin, dass viele große Marken zu jenen Tabakkonzernen gehören, die seit Jahrzehnten am Zigarettenverkauf verdienen.

## Doppelkonsum erhöht das Risiko

Oft wird die E-Zigarette als Umstiegshilfe für Raucher dargestellt. Die Studienlage ist laut ÖGP differenziert. Ein aktueller Cochrane-Review kommt zwar zu dem Ergebnis, dass nikotinhaltige E-Zigaretten beim Rauchstopp möglicherweise wirksamer sind als klassische Nikotinersatzprodukte – gemessen an der Rauchfreiheit nach mindestens sechs Monaten. Ob die Betroffenen langfristig ganz ohne Nikotin auskommen, lässt sich daraus aber nicht ableiten.

Dazu kommt ein weiteres Problem: 78 Prozent der E-Zigaretten-Nutzer rauchen zusätzlich Zigaretten oder Zigarren. Eine Meta-Analyse von 124 Studien zeigt, dass dieser Doppelkonsum durchgehend mit einem höheren Krankheitsrisiko verbunden ist als das Rauchen allein. Genannt werden unter anderem Herz-Kreislauf-Erkrankungen, Schlaganfall, Asthma und die chronisch obstruktive Lungenerkrankung COPD.

## Digitale Hilfe beim Ausstieg

Positiv bewerten die Lungenärzte digitale Unterstützungsangebote. Die Weltgesundheitsorganisation WHO empfiehlt SMS-Programme, Apps und Online-Angebote als Ergänzung zur Entwöhnungsbehandlung. Bei Jugendlichen konnte ein SMS-Programm die Chance, mit dem Vapen aufzuhören, um 35 Prozent erhöhen.

Wichtig ist der ÖGP dabei eine klare Einordnung: Digitale Werkzeuge ersetzen weder die ärztliche Beratung noch eine medikamentöse Therapie. Sie können eine Behandlung aber sinnvoll begleiten und gerade junge Menschen dort erreichen, wo sie ohnehin viel Zeit verbringen – am Smartphone.

Wer selbst oder im Familienkreis aufhören möchte, findet Unterstützung bei der Hausärztin oder dem Hausarzt sowie bei Fachärztinnen und Fachärzten für Lungenheilkunde.','gesundheit','Medizin',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/nikotin-jugendliche-oesterreich-vapes-nikotinbeutel-social-media.webp','Österreichische Gesellschaft für Pneumologie (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261024_OTS0007/nikotin-trend-bei-jugendlichen-social-media-foerdert-konsum-digitale-tools-helfen-beim-ausstieg','published','2026-10-24T16:50:00.000Z','2026-10-24T16:44:34.806Z','Nikotin bei Jugendlichen: Warnung vor Vapes und Pouches','Nikotin bei Jugendlichen: Fast jeder Dritte 14- bis 17-Jährige hat zuletzt gevapt. Was Lungenärzte zu Social Media und digitalen Ausstiegshilfen sagen.','Nikotin bei Jugendlichen','["Nikotin bei Jugendlichen","E-Zigarette Jugendliche","Nikotinbeutel","Vapes Österreich","Rauchstopp App","ÖGP Kongress Salzburg","Nikotinsucht Jugendliche Social Media","E-Zigarette aufhören Jugendliche"]','Nikotin bei Jugendlichen: Smartphone und bunte E-Zigarette auf einer Parkbank','Teenager''s hands holding a smartphone on a park bench in an Austrian town in autumn, a colorful disposable vape device lying on the bench beside a school backpack, fallen leaves, shallow depth of field, no faces, no text, no logos, no readable signs','[{"q":"Wie verbreitet sind E-Zigaretten unter Jugendlichen in Österreich?","a":"Laut ESPAD-Studie haben 29 Prozent der 14- bis 17-Jährigen in den letzten 30 Tagen eine E-Zigarette verwendet, 17 Prozent Nikotinbeutel. Knapp 8 Prozent der unter 18-Jährigen vapen laut LEAD-Studie täglich."},{"q":"Sind E-Zigaretten eine zugelassene Rauchentwöhnung?","a":"Nein. E-Zigaretten und Nikotinbeutel sind Konsumprodukte und keine zugelassenen Entwöhnungsmittel. Doppelkonsum mit Zigaretten ist laut Studien mit einem höheren Krankheitsrisiko verbunden."},{"q":"Was hilft Jugendlichen beim Aufhören?","a":"Die WHO empfiehlt SMS-Programme, Apps und Online-Angebote als Ergänzung zur ärztlichen Beratung. Ein SMS-Programm erhöhte bei Jugendlichen die Chance auf einen Vape-Stopp um 35 Prozent."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
